
import pylibxc
import pytest
from pylibxc.example_densities import test_data


def test_hyb_gga_xc_kmlyp_N_2_zk():
    # Prepare the input
    inp = test_data["N"]

    # Get the functional
    feval = pylibxc.LibXCFunctional("hyb_gga_xc_kmlyp", 2)
    if not feval._have_exc:
        pytest.skip("build lacks the derivative order for zk")

    # Evaluate only up to the tested field's derivative order. Computing higher
    # orders than this test checks is wasteful and can trip a latent bug in an
    # order the test does not exercise (e.g. an fxc segfault under a vrho test).
    out = feval.compute(inp, do_exc=feval._have_exc, do_vxc=False, do_fxc=False, do_kxc=False, do_lxc=False)
    ns = pylibxc.array_backend.array_namespace(out["zk"])
    tgt = out["zk"].flatten()
    ref_tgt = ns.full_like(tgt, ns.asarray([-1.949514557597645e+00, -1.911851340319573e+00, -1.859050150602024e+00, -1.785853528709414e+00, -1.686002200164786e+00, -1.552877953139288e+00, -1.381071088174034e+00, -1.169272014573598e+00, -9.245553720895381e-01, -6.680438528010139e-01, -4.485206938243735e-01, -3.545712849605263e-01, -3.175162472505886e-01, -2.608327888195300e-01, -1.848827178303069e-01, -1.088535293751465e-01, -5.272652571196267e-02, -2.294754339790828e-02, -6.699120107853757e-03, -1.083542565470435e-03]))
    error = ns.max(ns.abs(tgt-ref_tgt))/(1.0+ns.max(ns.asarray([ns.abs(tgt), ns.abs(ref_tgt)])))
    assert error < 5e-08


